import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';
import { Injectable, Logger, ServiceUnavailableException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import type { Bucket } from '@google-cloud/storage';
import { EnvironmentError, serviceAccountCredentials } from '../../config/environment';

// Object keys are generated by the API only: photos/<application>/<photo>.jpg or documents/<document>.pdf. Nothing user-supplied.
const KEY = /^(photos\/[0-9a-f-]{36}\/[0-9a-f-]{36}\.jpg|documents\/[0-9a-f-]{36}\.pdf)$/;
// Only these failure codes are logged; raw storage errors can contain bucket paths or credential details.
function storageFailureCode(error: unknown): string {
  const code = typeof error === 'object' && error !== null && 'code' in error ? String((error as { code: unknown }).code) : '';
  return /^(\d{3}|E[A-Z]+)$/.test(code) ? code : 'STORAGE_FAILED';
}

/** Private file storage for applicant photos and company documents: Google Cloud Storage in production, a local folder in development. */
@Injectable()
export class StorageService {
  private readonly logger = new Logger('Storage');
  private readonly driver: 'none' | 'local' | 'gcs';
  private readonly directory: string | null;
  private bucket: Promise<Bucket> | null = null;
  constructor(private readonly config: ConfigService) {
    this.driver = config.get('STORAGE_DRIVER') ?? 'none';
    // Production must never run without private storage: photos and signatures are required there. Staging may run
    // without a bucket (photos and signatures are then not collected), and must never use the production bucket.
    if (config.get('NODE_ENV') === 'production' && config.get('DEPLOYMENT_PURPOSE') !== 'staging' && this.driver !== 'gcs') throw new EnvironmentError('The production API requires STORAGE_DRIVER=gcs with GCS_BUCKET and GCS_CREDENTIALS_BASE64');
    this.directory = this.driver === 'local' ? resolve(config.getOrThrow<string>('STORAGE_LOCAL_DIR')) : null;
  }
  /** Photos and document signatures are only collected when storage is configured (always in production). */
  get enabled() { return this.driver !== 'none'; }
  private gcs(): Promise<Bucket> {
    this.bucket ??= import('@google-cloud/storage').then(({ Storage }) => {
      const credentials = serviceAccountCredentials(this.config.getOrThrow<string>('GCS_CREDENTIALS_BASE64'))!;
      return new Storage({ credentials: { client_email: credentials.client_email, private_key: credentials.private_key }, projectId: credentials.project_id,
        retryOptions: { autoRetry: true, maxRetries: 2 } }).bucket(this.config.getOrThrow<string>('GCS_BUCKET'));
    });
    return this.bucket;
  }
  private path(key: string) {
    const path = resolve(this.directory!, ...key.split('/'));
    if (!KEY.test(key) || !path.startsWith(this.directory! + sep)) throw new Error('Invalid storage key');
    return path;
  }
  private async run<T>(action: string, work: () => Promise<T>): Promise<T> {
    if (!this.enabled) throw new ServiceUnavailableException('File storage is not configured.');
    try { return await work(); }
    catch (error) {
      this.logger.error(`Storage ${action} failed: ${storageFailureCode(error)}`);
      throw new ServiceUnavailableException('File storage is unavailable. Please try again.');
    }
  }
  /** Stores a new object. Keys are never reused, so an existing object is never overwritten. */
  put(key: string, body: Buffer, contentType: 'image/jpeg' | 'application/pdf') {
    return this.run('upload', async () => {
      if (!KEY.test(key)) throw new Error('Invalid storage key');
      if (this.directory) { const path = this.path(key); await mkdir(dirname(path), { recursive: true }); await writeFile(path, body, { flag: 'wx' }); return; }
      await (await this.gcs()).file(key).save(body, { contentType, resumable: false, validation: 'crc32c', preconditionOpts: { ifGenerationMatch: 0 } });
    });
  }
  get(key: string): Promise<Buffer> {
    return this.run('download', async () => this.directory ? readFile(this.path(key)) : (await (await this.gcs()).file(key).download())[0]);
  }
  /** Best effort: a failed removal is logged (code only) and never fails the caller. */
  async remove(key: string): Promise<void> {
    try { await this.run('removal', async () => { if (this.directory) await rm(this.path(key), { force: true }); else await (await this.gcs()).file(key).delete({ ignoreNotFound: true }); }); }
    catch { /* logged by run() */ }
  }
}
export const photoKey = (applicationId: string, photoId: string) => `photos/${applicationId}/${photoId}.jpg`;
export const documentKey = (documentId: string) => `documents/${documentId}.pdf`;
